-- favo:requires-approval drops the refunds table and the refund_status enum (L02: FAVO does not process refunds); refuses, changing nothing, if refunds holds any row
-- AT-174: refunds go.
-- Spec: docs/FAVO_PRD_v7.md L02, §10.1 (refunds + the refund_status enum),
-- §11.1, REQ-060. Generated by drizzle-kit from db/schema.ts, then hand-edited
-- to be re-runnable (IF EXISTS) so a half-applied run can be repeated.
--
--   refunds        dropped. No code reads or writes it; requestRefund /
--                  approveRefund, the Yoco refund call and the webhook branch
--                  are already gone.
--   refund_status  dropped with it.
--
-- payment_status lost its refund value in 0043 (AT-201); nothing to do here.
--
-- It refuses, touching nothing, if refunds holds any row: dropping it would
-- lose a money record that nothing could recreate. No CASCADE — if anything
-- still depends on the table, the drop fails loudly instead of taking it along.
--
-- The reverse is drizzle/down/0049_at174_drop_refunds.down.sql.

DO $$
BEGIN
  IF to_regclass('public.refunds') IS NOT NULL THEN
    IF EXISTS (SELECT 1 FROM "refunds") THEN
      RAISE EXCEPTION 'AT-174/0049: refunds holds rows — not dropping, nothing changed';
    END IF;
  END IF;
END $$;--> statement-breakpoint
DROP TABLE IF EXISTS "refunds";--> statement-breakpoint
DROP TYPE IF EXISTS "public"."refund_status";
